<script setup>
const { data, pending, error, refresh } = await useApiFetch('/api/me/replays', { key: 'my-replays', lazy: import.meta.client, default: () => null })
const selected = ref(''), replay = shallowRef(null), loading = ref(false), playbackError = ref('')
let generation = 0
const when = value => new Date(value).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
const duration = value => `${Math.floor(value / 60000)}m ${Math.floor(value / 1000) % 60}s`
async function open(row) {
  const current = ++generation
  selected.value = row.id; replay.value = null; loading.value = true; playbackError.value = ''
  try { const value = await apiFetch(`/api/me/replays/${row.id}`); if (current === generation) replay.value = value }
  catch (e) { if (current === generation) playbackError.value = e.data?.statusMessage || 'Could not load this replay.' }
  finally { if (current === generation) loading.value = false }
}
watch(data, () => { generation++; selected.value = ''; replay.value = null; loading.value = false })
useHead({ title: 'Your replays | Ranked World', meta: [{ name: 'robots', content: 'noindex, nofollow' }] })
</script>

<template>
  <main id="main" class="wrap section replays-page">
    <header class="replays-header"><h1>Replays</h1><button v-if="data && !pending" class="btn btn--ghost" @click="refresh">Refresh</button></header>
    <div v-if="pending && !data" class="card replays-loading" role="status">Loading your replay library...</div>
    <div v-else-if="error" class="card"><EmptyState icon="play" title="Your replays are unavailable" :body="error.data?.statusMessage || 'Sign in or try again in a moment.'"><NuxtLink v-if="error.statusCode === 401" class="btn btn--brand" to="/sign-in">Sign in</NuxtLink><button v-else class="btn btn--brand" @click="refresh">Try again</button></EmptyState></div>
    <template v-else-if="data">
      <section v-show="!replay" class="replays-basic" aria-label="Basic statistics"><div><b>{{ data.basic.rounds }}</b><span>Scored rounds</span></div><div><b>{{ data.basic.tags }}</b><span>Tags</span></div><div><b>{{ data.basic.untaggedSeconds }}s</b><span>Untagged runtime</span></div><div><b>{{ data.basic.wins }}</b><span>Wins</span></div><p>{{ data.basic.scope }}</p></section>
      <section v-if="data.locked" class="replays-locked"><div class="replays-locked__copy"><span class="chip">Plus and Pro</span><h2>Replay playback</h2><p>Watch player wireframes on captured map geometry. Scrub the timeline, change your camera and inspect the movement behind each round.</p><p class="meta">Plus includes your 10 most recent eligible replays from 7 days, up to 15 minutes each. Pro includes 100 from 30 days, up to 60 minutes each. Both include all available replay statistics.</p><NuxtLink class="btn btn--brand btn--large" to="/subscribe">Compare plans</NuxtLink></div><div class="replays-preview" aria-label="Locked feature preview. No replay data."><div><span>Distance and speed</span><b class="replays-preview__blur" aria-hidden="true">123.4 m · 5.6 m/s</b><small>Included with Plus</small></div><div><span>Player perspectives</span><b>First person · Third person</b></div><div><span>Replay controls</span><b>Timeline · Free camera</b></div><p>Placeholder preview, not your statistics. No replay data is loaded.</p></div></section>
      <div v-else-if="data.consentRequired" class="card"><EmptyState icon="shield" title="Replay consent is required" body="Manage your movement recording consent in your account before opening replays."><NuxtLink class="btn btn--brand" to="/settings">Account settings</NuxtLink></EmptyState></div>
      <template v-else>
        <div v-if="replay" class="replays-library-heading"><button class="btn btn--ghost" @click="replay = null; selected = ''"><AppIcon name="arrowLeft" />Back to library</button><p class="meta">{{ replay.map }} · {{ when(replay.startedAt) }}</p></div>
        <div v-else class="replays-library-heading"><h2>Your library</h2><p class="meta">{{ data.rows.length }} / {{ data.limits.count }} replays · Last {{ data.limits.days }} days · Up to {{ data.limits.minutes }} minutes each</p></div>
        <div v-if="!data.rows.length" class="card"><EmptyState icon="play" title="No eligible replays yet" body="Completed recordings you participated in appear here within your plan's history window. Recording requires consent and available telemetry."><NuxtLink class="btn btn--brand" to="/play">Find a game</NuxtLink></EmptyState></div>
        <div v-else v-show="!replay" class="replays-library" aria-label="Your replay library"><button v-for="row in data.rows" :key="row.id" class="replay-entry" :class="{ 'is-selected': selected === row.id }" :aria-pressed="selected === row.id" @click="open(row)"><span class="replay-entry__map">{{ row.map }}</span><b>{{ row.kind.replaceAll('_', ' ') }}</b><span>{{ when(row.startedAt) }}</span><small>{{ duration(row.actualDurationMs ?? row.durationMs) }}<em>{{ selected === row.id ? 'Selected' : 'Watch replay' }}</em></small><small v-if="row.clipped">Preview first {{ Math.floor(row.durationMs / 60000) }}m</small></button></div>
        <div v-if="loading" class="card replays-loading" role="status">Loading the recorded map and player movement...</div>
        <div v-else-if="playbackError" class="card replays-loading" role="alert">{{ playbackError }}<button class="btn btn--ghost" @click="open({ id: selected })">Try again</button></div>
        <ClientOnly><ReplayViewer v-if="replay" :key="replay.id" :replay="replay" /></ClientOnly>
      </template>
    </template>
  </main>
</template>

<style scoped>
.replays-header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:28px}.replays-header h1{font-size:clamp(32px,5vw,48px);letter-spacing:-.04em;margin:10px 0}.replays-header .eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:var(--color-brand)}.replays-header p{max-width:600px;line-height:1.7}.replays-basic{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:24px;border:1px solid var(--surface-4);border-radius:16px;background:var(--surface-1);margin-bottom:32px}.replays-basic b{display:block;font-size:30px;font-variant-numeric:tabular-nums;letter-spacing:-.04em}.replays-basic span{display:block;color:var(--color-text-secondary);font-size:12px;margin-top:7px}.replays-basic p{grid-column:1/-1;font-size:11px;color:var(--color-text-secondary);border-top:1px solid var(--surface-4);padding-top:14px}.replays-locked{display:grid;grid-template-columns:1.15fr 1fr;gap:36px;padding:36px;border:1px solid var(--surface-4);border-radius:20px;background:radial-gradient(ellipse at 90% 0%,color-mix(in srgb,var(--color-brand) 9%,transparent),transparent 65%),var(--surface-1)}.replays-locked h2{font-size:30px;margin:18px 0 14px;letter-spacing:-.03em}.replays-locked p{font-size:14px;line-height:1.8;margin-bottom:18px}.replays-locked .meta{font-size:12px}.replays-preview{align-self:center;display:grid;gap:12px;border:1px solid var(--surface-4);padding:24px;border-radius:14px;background:var(--surface-0)}.replays-preview>div{padding:16px 0;border-bottom:1px solid var(--surface-4)}.replays-preview span{display:block;font-size:11px;color:var(--color-text-secondary);margin-bottom:10px}.replays-preview b{font-size:16px}.replays-preview p{font-size:11px;color:var(--color-text-secondary);margin:4px 0 0}.replays-library-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:18px}.replays-library-heading h2{font-size:20px}.replays-library-heading p{font-size:12px}.replays-library{display:flex;gap:12px;overflow-x:auto;padding-bottom:16px;margin-bottom:12px;scroll-snap-type:x proximity}.replay-entry{min-width:220px;max-width:260px;flex:0 0 230px;border:1px solid var(--surface-4);border-radius:14px;background:var(--surface-1);padding:18px;text-align:left;color:var(--color-text-primary);cursor:pointer;scroll-snap-align:start}.replay-entry.is-selected{border-color:var(--color-brand);background:color-mix(in srgb,var(--color-brand) 6%,var(--surface-1))}.replay-entry__map{font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--color-brand)}.replay-entry b{display:block;font-size:16px;margin:10px 0;text-transform:capitalize}.replay-entry>span:not(:first-child){font-size:12px;color:var(--color-text-secondary)}.replay-entry small{display:flex;justify-content:space-between;margin-top:20px;font-size:11px;color:var(--color-text-secondary)}.replay-entry em{font-style:normal;color:var(--color-text-primary)}.replays-loading{padding:36px;display:flex;align-items:center;justify-content:space-between;gap:20px;color:var(--color-text-secondary)}@media(max-width:760px){.replays-locked{grid-template-columns:1fr;padding:24px;gap:20px}.replays-library-heading{display:block}.replays-library-heading p{margin-top:8px}.replays-basic{grid-template-columns:repeat(2,1fr);gap:24px}.replays-header{align-items:flex-start}.replays-header .btn{margin-top:25px}}
</style>

<style scoped>.replays-preview__blur{filter:blur(6px);user-select:none}.replays-preview small{display:block;font-size:11px;color:var(--color-text-secondary);margin-top:10px}</style>
